import {rupiah,escapeHtml as e,quantity,cleanCart,addItem,cartLines,subtotal,orderMessage,whatsappLink,hasPrice,priceLabel,unpricedCount} from './commerce.js';

const app = document.querySelector('#app');
const cartDialog = document.querySelector('#cart-dialog');
const searchDialog = document.querySelector('#search-dialog');
const imageDialog = document.querySelector('#image-dialog');
const icons = {
 arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>', search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
 bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',minus:'<path d="M5 12h14"/>',plus:'<path d="M5 12h14M12 5v14"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',truck:'<path d="M2 5h12v12H2zM14 9h4l4 4v4h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
 shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6L12 2Z"/><path d="m8 11 3 3 5-5"/>',
 whatsapp:'<path d="M20.5 11.5a8.5 8.5 0 0 1-12.6 7.4L3 21l1.7-5a8.5 8.5 0 1 1 15.8-4.5Z"/><path d="M8 7c-2 3 4 9 7 7l1-2-3-1-1 1-2-2 1-1-1-2Z"/>',
 filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',
 back:'<path d="M20 12H4m6-6-6 6 6 6"/>',zoom:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5M7 10h6M10 7v6"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
const img = (name,alt,cls='',eager=false) => `<img class="${cls}" src="assets/images/${name}" alt="${e(alt)}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" width="1200" height="1600">`;
const link = (href,text,cls='text-link') => `<a class="${cls}" href="${href}">${text}${icon('arrow')}</a>`;
const productHref = p => `#/produk/${p.id}`;
function read(key,fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
let cart = cleanCart(read(config.storageKey,[]),products);
let favorites = read(config.storageKey+'-favorites',[]);
if (!Array.isArray(favorites)) favorites=[];
favorites=favorites.filter(id=>findProduct(id));
let selectedVariant = '', selectedQuantity=1, galleryIndex=0, detailId='', customerDraft={}, toastTimer, revealObserver, filterPanelOpen=false, filterNavigation=false;
const cardVariants = new Map();
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const totalLabel=()=>cartLines(cart,products).some(l=>l.total!==null)?rupiah(subtotal(cart,products)):'Menunggu konfirmasi';
const pendingNote=()=>unpricedCount(cart,products)?`<p class="pending-price-note">${unpricedCount(cart,products)} pcs dengan harga konfirmasi belum termasuk subtotal. Admin akan menghitung total lengkap.</p>`:'';
document.body.dataset.theme=config.theme;
const count = () => cart.reduce((n,l)=>n+l.qty,0);
function route() { const [path,query='']=(location.hash.slice(1)||'/').split('?'); return {path,params:new URLSearchParams(query)}; }
function toast(message,action=false) {
 const node=document.querySelector('#toast'); node.innerHTML='<span>'+e(message)+'</span>'+(action?'<button data-action="cart">Lihat keranjang '+icon('arrow')+'</button>':'');
 node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),4500);
}
function persist() { try {localStorage.setItem(config.storageKey,JSON.stringify(cart));} catch { toast('Keranjang tersimpan selama halaman ini terbuka.'); } }
function favorite(id) { favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id]; try{localStorage.setItem(config.storageKey+'-favorites',JSON.stringify(favorites));}catch{} document.querySelectorAll(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('saved',favorites.includes(id));b.setAttribute('aria-pressed',String(favorites.includes(id)));}); toast(favorites.includes(id)?'Ditambahkan ke koleksi favorit.':'Dihapus dari koleksi favorit.'); if(route().path==='/favorit') render(false); }
function header() {
 const {path}=route();
 return `<div class="announcement"><span>HIJAB, MUKENA & A LITTLE EVERYDAY CONFIDENCE</span><a href="#/usaha">Mulai cerita usahamu ${icon('arrow')}</a></div>
 <header class="site-header"><button class="icon-button mobile-menu" data-action="menu" aria-label="Buka menu" aria-expanded="false">${icon('menu')}</button>
 <a href="#/" class="wordmark" aria-label="VUYAMA Beranda">VUYAMA<span>HIJAB & MUKENA</span></a>
 <nav class="main-nav" aria-label="Navigasi utama">${[['/','Beranda'],['/produk','Koleksi'],['/usaha','Mulai Usaha'],['/tentang','Tentang Vuyama']].map(([url,label])=>`<a href="#${url}" ${(url==='/'?path==='/':path.startsWith(url))?'aria-current="page"':''}>${label}</a>`).join('')}<a class="mobile-cart-link" href="#/favorit">Favorit</a><a class="mobile-cart-link" href="#/keranjang">Keranjang</a></nav>
 <div class="header-actions"><button class="icon-button" data-action="search" aria-label="Cari produk">${icon('search')}</button><a class="icon-button favorites-link" href="#/favorit" aria-label="Produk favorit">${icon('heart')}</a><button class="icon-button cart-trigger" data-action="cart" aria-label="Buka keranjang">${icon('bag')}<span class="cart-count" ${count()?'':'hidden'}>${count()}</span></button></div></header>`;
}
function footer() {return `<footer class="site-footer"><div class="footer-main"><div><a class="footer-brand" href="#/">VUYAMA</a><p>Grace. Confidence. You.<br>Hijab dan mukena untuk setiap versi dirimu.</p><a href="${config.instagram}" target="_blank" rel="noopener" class="social-link">Instagram @vuyama.id ↗</a></div><div><span class="eyebrow">TEMUKAN PILIHANMU</span><a href="#/produk">Semua koleksi</a><a href="#/produk?category=Pashmina">Pashmina</a><a href="#/produk?category=Mukena">Mukena</a><a href="#/favorit">Favorit kamu</a></div><div><span class="eyebrow">LET'S GROW TOGETHER</span><a href="#/usaha">Paket usaha & reseller</a><a href="#/tentang">Tentang Vuyama</a><a href="${config.officialLinks}" target="_blank" rel="noopener">Tautan resmi Vuyama ↗</a><a href="${whatsappLink(config.whatsapp,'Halo Vuyama, saya ingin bertanya tentang katalog.')}" target="_blank" rel="noopener">Chat ${config.admin} ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} VUYAMA. All rights reserved.</span><span>Cibinong, Bogor · Indonesia</span><span>Made for your everyday.</span></div></footer>`;}
function card(p) {
 const params=route().params,color=params.get('color'),q=params.get('q')?.trim().toLowerCase();
 const match=p.variants.find(v=>(color&&v.family===color)||(q&&v.name.toLowerCase().includes(q)));
 const v=match||p.variants.find(v=>v.id===cardVariants.get(p.id))||p.variants.find(v=>canOrder(p,v))||p.variants[0];const touched=cardVariants.has(p.id)||Boolean(match);const photo=touched?v.image:p.images[0];
 return `<article class="product-card" data-product="${p.id}"><div class="product-photo ${p.contain||v.contain?'contain-photo':''}"><a href="${productHref(p)}" aria-label="Lihat ${e(p.name)}">${img(photo,p.name+(touched?' — '+v.name:' — foto koleksi'),'card-primary')}${!touched&&p.images[1]?img(p.images[1],p.name+' sudut lain','hover-image'):''}</a><span class="product-type">${e(p.category)}</span><button class="favorite-button ${favorites.includes(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="Simpan ${e(p.name)} ke favorit" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button><a href="${productHref(p)}" class="quick-view">Lihat detail ${icon('arrow')}</a></div><div class="product-info"><span class="product-material">${e(p.material)}</span><div class="card-title-row"><h3><a href="${productHref(p)}">${e(p.name)}</a></h3><span class="product-price ${hasPrice(p)?'':'quote-price'}">${priceLabel(p)}</span></div><div class="card-swatches">${p.variants.filter(v=>v.imageIsExact&&v.image!=='catalogue-placeholder.svg').slice(0,5).map(v=>`<span class="mini-variant" title="${e(v.name)}">${img(v.image,v.name)}</span>`).join('')}<span class="variant-label">${p.variants.length} ${p.variants.length>1?'varian':'pilihan'}</span></div><label class="card-variant"><span class="sr-only">Varian ${e(p.name)}</span><select data-card-variant="${p.id}" aria-label="Varian ${e(p.name)}">${p.variants.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${e(x.name)}${canOrder(p,x)?'':' · '+availabilityLabel(p,x)}</option>`).join('')}</select>${icon('chevron')}</label><button class="card-add" ${canOrder(p,v)?'':'disabled'} data-quick-add="${p.id}" aria-label="Tambah ${e(p.name)} ke keranjang">${icon('plus')}<span>${canOrder(p,v)?'Tambah ke keranjang':availabilityLabel(p,v)}</span></button></div></article>`;
}
function sectionHead(eyebrow,title,more=true) {return `<div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${more?link('#/produk','Lihat semua koleksi'):''}</div>`;}
function benefits() {return `<div class="benefit-strip"><div>${icon('spark')}<span>Pilihan untuk setiap gaya<small>Pashmina, segi empat, hingga instan.</small></span></div><div>${icon('bag')}<span>Belanja dengan mudah<small>Pilih koleksi, susun pesananmu.</small></span></div><div>${icon('whatsapp')}<span>Dibantu secara personal<small>Lanjutkan pesanan melalui WhatsApp.</small></span></div></div>`;}
function editorialHome() {return `
 <section class="v-hero"><div class="v-hero-copy"><span class="eyebrow"><i></i> THE VUYAMA COLLECTION</span><h1>Untuk setiap<br><em>versi dirimu.</em></h1><p>Dari langkah kecil setiap pagi, hingga momen yang berarti. Temukan hijab dan mukena yang terasa seperti kamu.</p><div class="hero-cta">${link('#/produk','Jelajahi koleksi','button')}<a href="#/tentang" class="quiet-link">Kenali Vuyama ${icon('arrow')}</a></div><div class="hero-footnote"><span>THOUGHTFULLY CHOSEN.<br>BEAUTIFULLY YOU.</span><a href="#story" data-action="scroll-story" aria-label="Jelajahi cerita koleksi">↓</a></div></div>
 <div class="v-hero-visual">${img('gradasi-cream.webp','Koleksi Viscose Gradasi Creamy Nude Vuyama','hero-main',true)}<div class="hero-visual-top"><span>THE COLOUR EDIT</span><span>01 / VUYAMA</span></div><a class="hero-feature" href="#/produk/viscose-gradasi"><span><small>MEET YOUR NEW FAVOURITE</small><strong>Viscose Gradasi</strong></span><span class="circle-arrow">${icon('arrow')}</span></a></div></section>
 <div class="v-intro-strip"><span>Soft colours. <em>Endless possibilities.</em></span><div><span>Pashmina</span><b>·</b><span>Hijab instan</span><b>·</b><span>Mukena</span></div></div>
 <section class="section v-categories">${sectionHead('A PLACE FOR EVERY STYLE','Temukan yang <em>kamu suka.</em>',false)}<div class="category-grid">${[['Pashmina','gradasi.webp','Ringan dalam setiap cerita.'],['Instan','hayla.webp','Siap melangkah, tanpa ribet.'],['Segi Empat','paris-japan.webp','Klasik yang selalu terasa pas.'],['Mukena','segenggam-polos.webp','Temani momen paling tenang.']].map(([name,photo,desc],i)=>`<a class="category-tile" href="#/produk?category=${encodeURIComponent(name)}">${img(photo,'Koleksi '+name+' Vuyama')}<span class="category-number">0${i+1}</span><div><h3>${name==='Instan'?'Hijab Instan':name}</h3><p>${desc}</p><span class="circle-arrow">${icon('arrow')}</span></div></a>`).join('')}</div></section>
 <section class="v-colour-story" id="story"><div class="colour-main">${img('gradasi.webp','Blushy Rose — Viscose Gradasi')}<span>BLUSHY ROSE / VISCOSE GRADASI</span></div><div class="colour-copy"><span class="eyebrow">A LITTLE COLOUR, A LITTLE YOU</span><h2>Satu hijab.<br><em>Banyak cerita.</em></h2><p>Lembutnya warna bertemu dengan caramu bercerita. Jelajahi gradasi yang berbeda, dan temukan perpaduan yang paling kamu.</p><div class="colour-preview">${['#c7b6bc','#c9c0b4','#ab7794','#a1a89b','#838790','#373338'].map(c=>`<i style="background:${c}"></i>`).join('')}<span>12 perpaduan warna</span></div>${link('#/produk/viscose-gradasi','Temukan warna kamu','button')}<div class="colour-small">${img('gradasi-burnt-maho.webp','Viscose Gradasi Burnt Maho')}<span>YOUR EVERYDAY,<br>A LITTLE MORE<br><em>colourful.</em></span></div></div></section>
 <section class="section collection-section">${sectionHead('YOUR NEXT EVERYDAY FAVOURITE','Pilihan untuk <em>harimu.</em>')}<div class="product-grid">${['modal-viscose','viscose-gradasi','printed-viscose','hayla-khiban'].map(id=>findProduct(id)).filter(Boolean).map(card).join('')}</div></section>
 ${benefits()}<section class="v-business"><div><span class="eyebrow">GROW WITH VUYAMA</span><h2>Mimpi punya brand sendiri?<br><em>Mulai dari sini.</em></h2></div><div><p>Jelajahi pilihan paket usaha, produk tanpa label, dan kebutuhan kemasan untuk langkah pertama brand kamu.</p>${link('#/usaha','Lihat pilihan usaha','button')}</div></section>
 <section class="v-social"><div><span class="eyebrow">A LITTLE CLOSER TO US</span><h2>See you on <em>Instagram.</em></h2></div><a href="${config.instagram}" target="_blank" rel="noopener" class="text-link">@vuyama.id ↗</a></section>`;}
function catalog({home=false}={}) {
 const {params}=route(); const q=params.get('q')||'',category=params.get('category')||'Semua',color=params.get('color')||'',sort=params.get('sort')||'curated';
 const max=Number(params.get('max')||0);
 let list=retailProducts.filter(p=>(category==='Semua'||p.category===category)&&(!color||p.colorFamily===color||p.variants.some(v=>v.family===color))&&(!max||(hasPrice(p)&&p.price<=max))&&(!q||`${p.name} ${p.category} ${p.material} ${p.variants.map(v=>v.name).join(' ')}`.toLowerCase().includes(q.toLowerCase())));
 if(sort==='price-asc'||sort==='price-desc')list.sort((a,b)=>!hasPrice(a)?(!hasPrice(b)?0:1):!hasPrice(b)?-1:sort==='price-asc'?a.price-b.price:b.price-a.price); if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
 return `${home?'':`<div class="page-intro"><span class="eyebrow">THE COLLECTION</span><h1>${q?'Hasil pencarian.':'Temukan pilihanmu.'}</h1><p>${q?`Untuk “${e(q)}”`:`${retailProducts.length} koleksi, berbagai cerita. Temukan pilihan untuk setiap harimu.`}</p></div>`}
 ${catalogDiscovery(q,category)}<div class="catalog-layout"><aside class="filter-panel ${filterPanelOpen?'mobile-open':''}" id="catalog-filters" aria-label="Filter produk"><div class="filter-title"><span>Filter Koleksi</span><button class="filter-close icon-button" data-action="filters" aria-label="Tutup filter">${icon('close')}</button>${icon('filter')}</div><div class="filter-group"><h3>Kategori</h3>${categories.map(c=>`<label><input type="radio" name="category" value="${c}" ${c===category?'checked':''} data-filter="category"><span>${c}</span><small>${c==='Semua'?retailProducts.length:retailProducts.filter(p=>p.category===c).length}</small></label>`).join('')}</div><div class="filter-group"><h3>Nuansa Warna</h3>${[['Putih','#eee9de'],['Pink','#d7b2c9'],['Lavender','#bab1bf'],['Taupe','#b6a2a8'],['Hitam','#373038'],['Biru','#9faec4'],['Hijau','#a4aa93'],['Motif','#986c77']].map(([c,hex])=>`<label><input type="radio" name="color" value="${c}" ${c===color?'checked':''} data-filter="color"><span class="filter-color" style="--swatch:${hex}"></span><span>${c}</span></label>`).join('')}</div><div class="filter-group"><label class="field-label" for="max-price">Harga maksimum</label><select id="max-price" data-filter="max"><option value="">Semua harga</option>${[50000,75000,100000,200000,350000].map(n=>`<option value="${n}" ${max===n?'selected':''}>${rupiah(n)}</option>`).join('')}</select></div><button class="text-link reset-filter" data-action="reset-filters">Reset filter ${icon('close')}</button></aside>
 <div class="catalog-results"><div class="catalog-toolbar"><div><h2>${home?'Koleksi pilihan':'Semua koleksi'}</h2><span>${list.length} produk${category!=='Semua'?' · '+e(category):''}</span></div><div class="toolbar-actions"><button class="filter-toggle" data-action="filters" aria-controls="catalog-filters" aria-expanded="${filterPanelOpen}">${icon('filter')} Filter</button><label class="sr-only" for="sort-products">Urutkan produk</label><select id="sort-products" data-filter="sort"><option value="curated" ${sort==='curated'?'selected':''}>Pilihan koleksi</option><option value="price-asc" ${sort==='price-asc'?'selected':''}>Harga terendah</option><option value="price-desc" ${sort==='price-desc'?'selected':''}>Harga tertinggi</option><option value="name" ${sort==='name'?'selected':''}>Nama A–Z</option></select></div></div>${(q||color||category!=='Semua'||max)?`<div class="active-filters"><span>${[q?`Pencarian: ${e(q)}`:'',category!=='Semua'?e(category):'',color?e(color):'',max?`≤ ${rupiah(max)}`:''].filter(Boolean).join(' / ')}</span><button data-action="reset-filters" aria-label="Hapus semua filter">${icon('close')}</button></div>`:''}<div class="product-grid">${list.map(card).join('')}</div>${!list.length?`<div class="empty-state">${icon('search')}<h2>Belum menemukan yang cocok?</h2><p>Coba kata kunci lain atau hapus filter yang dipilih.</p><button class="button" data-action="reset-filters">Lihat Semua Koleksi ${icon('arrow')}</button></div>`:''}<p class="catalog-note">Harga tercantum mengikuti katalog Vuyama September 2026. Produk berlabel konfirmasi harga dihitung bersama admin. Ketersediaan varian dikonfirmasi saat order.</p></div></div>`;
}
function detail(p) {
 if(detailId!==p.id){detailId=p.id;selectedVariant=cardVariants.get(p.id)||p.variants.find(v=>canOrder(p,v))?.id||p.variants[0].id;selectedQuantity=1;galleryIndex=0;}
 const variant=p.variants.find(v=>v.id===selectedVariant)||p.variants[0];
 const gallery=[...new Set([...(variant.image!=='catalogue-placeholder.svg'?[variant.image,...p.images]:[...p.images,variant.image]),...(p.referenceImages||[])])].filter(Boolean);
 galleryIndex=Math.min(galleryIndex,gallery.length-1);
 return `<div class="breadcrumb"><a href="#/">Beranda</a>${icon('chevron')}<a href="#/produk">Koleksi</a>${icon('chevron')}<span>${e(p.name)}</span></div><section class="detail-layout"><div class="product-gallery"><div class="gallery-thumbs">${gallery.map((name,i)=>`<button data-gallery="${i}" class="${galleryIndex===i?'selected':''}" aria-label="Lihat foto ${i+1}" aria-pressed="${galleryIndex===i}">${img(name,p.name+' foto '+(i+1))}</button>`).join('')}</div><button class="gallery-main ${p.contain||variant.contain?'contain-photo':''}" data-zoom="${gallery[galleryIndex]}" aria-label="Perbesar foto ${e(p.name)}">${img(gallery[galleryIndex],p.name+' '+variant.name,'',true)}<span>${icon('zoom')}</span></button></div><div class="detail-copy"><span class="eyebrow">${e(p.label)}</span><h1>${e(p.name)}</h1><div class="detail-price">${priceLabel(p)}${hasPrice(p)?`<span>/ ${p.unit||'pcs'}</span>`:''}</div><p class="price-caption">${p.category==='Paket Usaha'?'Harga paket katalog September 2026':'Harga ecer · katalog September 2026'}</p><p class="detail-description">${e(p.description)}</p><div class="variant-picker"><div class="label-row"><span>Pilih varian</span><strong id="selected-color">${e(variant.name)}</strong></div><div class="variant-tiles ${p.variants.length>12?'many-variants':''}">${p.variants.map(v=>`<button data-variant="${v.id}" class="${v.id===variant.id?'selected':''} ${canOrder(p,v)?'':'archived'}" title="${e(v.name)}" aria-label="Pilih ${e(v.name)}" aria-pressed="${v.id===variant.id}">${v.image!=='catalogue-placeholder.svg'?img(v.image,v.name):'<span class="variant-letter">'+e(v.name.slice(0,2))+'</span>'}<small>${e(v.name)}</small></button>`).join('')}</div><label class="detail-variant-select"><span class="sr-only">Varian ${e(p.name)}</span><select data-detail-select aria-label="Varian ${e(p.name)}">${p.variants.map(v=>`<option value="${v.id}" ${v.id===variant.id?'selected':''}>${e(v.name)}</option>`).join('')}</select></label><p class="fine-print">${variant.imageIsExact===false?'Foto koleksi atau kartu warna merupakan referensi; detail pilihan dikonfirmasi admin. ':''}Warna dapat sedikit berbeda karena pencahayaan dan layar.</p>${!canOrder(p,variant)?`<p class="stock-note">${availabilityLabel(p,variant)}. Hubungi admin untuk informasi terbaru.</p>`:''}</div><div class="detail-actions"><div><label class="field-label" for="detail-qty">Jumlah</label>${stepper({value:selectedQuantity,kind:'detail',id:'detail-qty'})}</div><button class="button add-to-cart" ${canOrder(p,variant)?'':'disabled'} data-add="${p.id}">${icon('bag')} ${canOrder(p,variant)?'Tambah ke Keranjang':availabilityLabel(p,variant)} ${icon('arrow')}</button><button class="detail-save icon-button ${favorites.includes(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="Simpan ke favorit" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button></div><p class="detail-order-note">${icon('whatsapp')} Selesaikan pesanan bersama admin melalui WhatsApp.</p><details open><summary>Detail Koleksi ${icon('plus')}</summary><dl><div><dt>Material</dt><dd>${e(p.material)}</dd></div><div><dt>Jenis</dt><dd>${e(p.category)}</dd></div>${p.size?`<div><dt>Ukuran</dt><dd>${e(p.size)}</dd></div>`:''}<div><dt>Varian pilihan</dt><dd>${e(variant.name)}</dd></div></dl></details>${p.sourceFolder?`<a class="text-link source-gallery-link" href="${e(p.sourceFolder.url)}" target="_blank" rel="noopener">Lihat seluruh foto katalog ${icon('arrow')}</a>`:''}${tierDetails(p)}<details><summary>Pengiriman & Pembayaran ${icon('plus')}</summary><p>Alamat dan pilihan pengiriman diteruskan ke admin. Ketersediaan, ongkos kirim, total akhir, dan metode pembayaran dikonfirmasi melalui WhatsApp sebelum kamu membayar.</p></details></div></section><section class="section related-section">${sectionHead('COMPLETE YOUR EVERYDAY EDIT','Mungkin kamu juga suka.')}<div class="product-grid">${retailProducts.filter(x=>x.id!==p.id&&x.availability!=='coming-soon').slice(0,4).map(card).join('')}</div></section>`;
}
function stepper({value,kind,id,index}) {return `<div class="quantity-stepper"><button type="button" data-qty="${kind}" data-index="${index??''}" data-delta="-1" aria-label="Kurangi jumlah" ${value<=1?'disabled':''}>${icon('minus')}</button><input id="${id}" class="qty-input" inputmode="numeric" type="number" min="1" max="99" value="${value}" data-qty-input="${kind}" data-index="${index??''}" aria-label="Jumlah produk"><button type="button" data-qty="${kind}" data-index="${index??''}" data-delta="1" aria-label="Tambah jumlah" ${value>=99?'disabled':''}>${icon('plus')}</button></div>`;}
function cartRows(compact=false) {return cartLines(cart,products).map((l,i)=>`<article class="cart-row ${compact?'compact':''}"><a class="cart-image" href="${productHref(l.product)}" data-close-cart>${img(l.color.image,l.product.name+' '+l.color.name)}</a><div class="cart-product"><span class="product-material">${e(l.product.category)}</span><h3><a href="${productHref(l.product)}" data-close-cart>${e(l.product.name)}</a></h3><p>${e(l.color.name)}</p><span>${priceLabel(l.product)} / ${l.product.unit||'pcs'}</span></div><div class="cart-quantity">${stepper({value:l.qty,kind:'cart',id:`${compact?'drawer':'cart'}-qty-${i}`,index:i})}<button class="remove-item" data-remove="${i}">Hapus</button></div><strong class="line-total">${l.total===null?'Konfirmasi harga':rupiah(l.total)}</strong></article>`).join('');}
function summary(checkout=false) {return `<div class="order-summary"><span class="eyebrow">YOUR EVERYDAY EDIT</span><h2>Ringkasan pesanan</h2>${checkout?`<div class="checkout-lines">${cartLines(cart,products).map(l=>`<div>${img(l.color.image,l.product.name)}<span><strong>${e(l.product.name)}</strong><small>${e(l.color.name)} · ${l.qty} ${l.product.unit||'pcs'}</small></span><b>${l.total===null?'Konfirmasi harga':rupiah(l.total)}</b></div>`).join('')}</div>`:''}<dl class="totals"><div><dt>${unpricedCount(cart,products)?'Produk berharga':'Subtotal'} (${count()-unpricedCount(cart,products)} item)</dt><dd>${totalLabel()}</dd></div><div><dt>Ongkos kirim</dt><dd>Dikonfirmasi admin</dd></div><div class="total-row"><dt>${unpricedCount(cart,products)?'Subtotal sementara':'Subtotal produk'}</dt><dd>${totalLabel()}</dd></div></dl>${pendingNote()}<p class="summary-note">Total akhir termasuk ongkir akan dikonfirmasi melalui WhatsApp.</p>${checkout?'':link('#/checkout','Lanjut ke Checkout','button full-width')}<div class="secure-note">${icon('shield')} Pesanan dikonfirmasi sebelum pembayaran.</div></div>`;}
function emptyCart() {return `<div class="empty-state">${icon('bag')}<span class="eyebrow">A NEW STORY STARTS HERE</span><h2>Keranjangmu masih kosong.</h2><p>Ada pilihan yang menunggu untuk menjadi favoritmu.</p>${link('#/produk','Jelajahi Koleksi','button')}</div>`;}
function cartPage() {return `${checkoutSteps(2)}<div class="page-intro"><span class="eyebrow">YOUR PERSONAL SELECTION</span><h1>Keranjang kamu.</h1><p>Periksa kembali pilihanmu sebelum melanjutkan.</p></div>${cart.length?`<div class="cart-layout"><div><div class="cart-table-head"><span>Produk</span><span>Jumlah</span><span>Subtotal</span></div><div class="cart-items">${cartRows()}</div>${link('#/produk','Lanjutkan Belanja','text-link back-link')}</div>${summary()}</div>`:emptyCart()}`;}
function field(name,label,{type='text',required=true,placeholder='',textarea=false,autocomplete='',pattern=''}={}) {const attrs=`id="field-${name}" name="${name}" ${required?'required':''} maxlength="${textarea?500:100}" ${autocomplete?`autocomplete="${autocomplete}"`:''} ${pattern?`pattern="${pattern}"`:''} placeholder="${placeholder}"`;return `<div class="form-field ${textarea?'span-2':''}"><label for="field-${name}">${label}${required?' <span>*</span>':' <small>(opsional)</small>'}</label>${textarea?`<textarea ${attrs} rows="3">${e(customerDraft[name]||'')}</textarea>`:`<input ${attrs} type="${type}" value="${e(customerDraft[name]||'')}">`}</div>`;}
function checkoutPage() {return `<div class="breadcrumb"><a href="#/keranjang">Keranjang</a>${icon('chevron')}<span>Checkout</span></div>${checkoutSteps(3)}<div class="page-intro checkout-intro"><span class="eyebrow">ONE STEP CLOSER</span><h1>Lengkapi ceritamu.</h1><p>Isi data pemesan, lalu lanjutkan bersama admin di WhatsApp.</p></div>${cart.length?`<div class="checkout-layout"><form id="checkout-form"><section class="checkout-form-section"><div class="form-heading"><span>01</span><h2>Data pemesan</h2></div><div class="form-grid">${field('name','Nama lengkap',{placeholder:'Nama penerima',autocomplete:'name'})}${field('phone','Nomor WhatsApp',{type:'tel',placeholder:'08xxxxxxxxxx',autocomplete:'tel',pattern:'(0|[+]62|62)[0-9]{8,13}'})}${field('address','Alamat lengkap',{textarea:true,placeholder:'Jalan, nomor rumah, RT/RW, kelurahan, kecamatan',autocomplete:'street-address'})}${field('city','Kota / Kabupaten',{placeholder:'Contoh: Kota Bogor',autocomplete:'address-level2'})}${field('postcode','Kode pos',{required:false,placeholder:'16100',autocomplete:'postal-code',pattern:'[0-9]{5}'})}</div></section><section class="checkout-form-section"><div class="form-heading"><span>02</span><h2>Preferensi pengiriman</h2></div><div class="form-field"><label for="field-shipping">Kurir pilihan</label><select id="field-shipping" name="shipping">${['Diskusikan dengan admin','JNE','J&T Express','SiCepat'].map(c=>`<option ${customerDraft.shipping===c?'selected':''}>${c}</option>`).join('')}</select><p class="fine-print">Pilihan kurir dan biaya pengiriman akan dikonfirmasi oleh admin.</p></div>${field('notes','Catatan pesanan',{textarea:true,required:false,placeholder:'Ada hal yang ingin disampaikan kepada admin?'})}</section><div class="checkout-how">${icon('whatsapp')}<div><strong>Selanjutnya, kita bertemu di WhatsApp.</strong><p>Detail produk dan data yang kamu isi akan dimasukkan ke pesan. Kamu bisa memeriksanya sebelum menekan kirim.</p></div></div><button type="submit" class="button checkout-submit">${icon('whatsapp')} Kirim Pesanan ke WhatsApp ${icon('arrow')}</button><a class="text-link checkout-back" href="#/keranjang">${icon('back')} Kembali ke Keranjang</a><div id="whatsapp-fallback" hidden></div></form>${summary(true)}</div>`:emptyCart()}`;}
function aboutPage() {return `<section class="about-hero"><div><span class="eyebrow">THE STORY BEHIND ${config.brand}</span><h1>Yang sederhana,<br>yang <em>berarti.</em></h1><p>Kami percaya, gaya personal dimulai dari pilihan kecil yang terasa tepat. Hijab yang kamu pilih hari ini adalah bagian dari cerita yang ingin kamu bawa.</p><p>Dari pashmina hingga mukena, dari pilihan untuk diri sendiri hingga langkah pertama usahamu. Vuyama hadir untuk menemani setiap cerita.</p>${link('#/produk','Temukan Koleksimu','button')}</div>${img('gradasi.webp','Koleksi hijab Vuyama')}</section><section class="section about-process">${sectionHead('SIMPLE FROM START TO FINISH','Belanja dalam tiga langkah.',false)}<div>${[['01','Pilih koleksimu','Jelajahi produk, lihat foto, dan pilih varian yang kamu sukai.'],['02','Susun pesanan','Tambahkan ke keranjang dan lengkapi data pengiriman.'],['03','Lanjutkan di WhatsApp','Admin mengonfirmasi varian, ongkir, dan pembayaran bersama kamu.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><div class="brand-contact"><span class="eyebrow">LET’S STAY CONNECTED</span><h2>Kenali Vuyama lebih dekat.</h2><p>Supplier hijab dan mukena dari Cibinong, Bogor. Ikuti cerita, pilihan warna, dan informasi terbaru melalui akun resmi kami.</p><a class="text-link" href="${config.instagram}" target="_blank" rel="noopener">Instagram @vuyama.id ↗</a><a class="text-link" href="${config.officialLinks}" target="_blank" rel="noopener">Hubungi admin resmi ↗</a></div>`;}
function favoritesPage() {return `<div class="page-intro"><span class="eyebrow">KEPT CLOSE TO YOUR HEART</span><h1>Favorit kamu.</h1><p>Simpan yang kamu suka, pilih saat kamu siap.</p></div>${favorites.length?`<div class="product-grid favorites-grid">${products.filter(p=>favorites.includes(p.id)).map(card).join('')}</div>`:`<div class="empty-state">${icon('heart')}<h2>Temukan favorit pertamamu.</h2><p>Tekan ikon hati pada koleksi yang kamu suka.</p>${link('#/produk','Jelajahi Koleksi','button')}</div>`}`;}

function canOrder(p,v){return Boolean(v)&&!['sold-out','coming-soon'].includes(v.availability||p.availability);}
function availabilityLabel(p,v){return (v?.availability||p.availability)==='coming-soon'?'Segera hadir':'Arsip · sold out';}
function tierDetails(p){return `${p.pricingTiers?.length?`<details class="reseller-pricing"><summary>Harga reseller & pembelian banyak ${icon('plus')}</summary><table class="price-tiers"><thead><tr><th>Jenis</th><th>Minimum</th><th>Harga / pcs</th></tr></thead><tbody>${p.pricingTiers.map(t=>`<tr><td>${e(t.label)}</td><td>${t.minQty} pcs</td><td>${rupiah(t.price)}</td></tr>`).join('')}</tbody></table><p class="source-note">Harga ecer digunakan dalam keranjang. Syarat reseller, mix warna, dan harga akhir pembelian banyak dikonfirmasi bersama admin sebelum pembayaran.</p></details>`:''}${p.priceNote?`<p class="source-note">${e(p.priceNote)}</p>`:''}${p.note?`<p class="source-note">${e(p.note)}</p>`:''}`;
}
function catalogDiscovery(q,category){return `<div class="catalog-discovery"><form class="catalog-inline-search" data-search-form>${icon('search')}<label class="sr-only" for="catalog-query">Cari koleksi atau warna</label><input id="catalog-query" type="search" name="q" value="${e(q)}" placeholder="Cari koleksi, material, atau warna…"><button type="submit">Cari ${icon('arrow')}</button></form><div class="category-chips" aria-label="Kategori koleksi">${categories.map(c=>`<a href="#/produk${c==='Semua'?'':'?category='+encodeURIComponent(c)}" class="${c===category?'active':''}" ${c===category?'aria-current="true"':''}>${c==='Semua'?'Semua koleksi':c}</a>`).join('')}</div></div>`;}
function checkoutSteps(step){return `<ol class="checkout-steps" aria-label="Tahap pemesanan">${[['Koleksi','#/produk'],['Keranjang','#/keranjang'],['Checkout','#/checkout']].map(([label,url],i)=>`<li class="${i+1===step?'active':''}" ${i+1===step?'aria-current="step"':''}><a href="${url}"><span>0${i+1}</span>${label}</a></li>`).join('')}<li><span>04</span> WhatsApp</li></ol>`;}
function businessPage(){return `<div class="page-intro business-intro"><span class="eyebrow">GROW WITH VUYAMA</span><h1>Brand impianmu,<br><em>dimulai di sini.</em></h1><p>Pilih paket usaha yang sesuai langkahmu. Lengkapi dengan label dan kemasan untuk menghadirkan identitas brand kamu sendiri.</p></div><nav class="business-nav" aria-label="Pilihan usaha"><a href="#business-packages" data-section="business-packages">Paket usaha <span>${packages.length}</span></a><a href="#business-services" data-section="business-services">Label & kemasan <span>${services.length}</span></a><a href="#/produk">Harga per produk ${icon('arrow')}</a></nav><p class="business-note">Harga mengacu pada pricelist September 2026. Ketersediaan, masa berlaku promo, pilihan warna, dan total akhir dikonfirmasi oleh admin.</p><section id="business-packages"><div class="business-heading"><h2>Paket untuk <em>mulai.</em></h2><span class="eyebrow">${packages.length} PILIHAN USAHA</span></div><div class="business-grid">${packages.map((p,i)=>`<article class="business-card"><span class="eyebrow">PAKET ${String(i+1).padStart(2,'0')}</span><h3>${e(p.name)}</h3><div class="business-price">${rupiah(p.price)} <small>/ paket</small></div>${p.previousPrice?`<p class="source-note">Harga promo katalog September 2026; masa berlaku dikonfirmasi admin.</p>`:''}<ul>${p.contents.map(c=>`<li>${e(c)}</li>`).join('')}</ul>${p.selection?`<p class="package-selection">${e(p.selection)}</p>`:''}<button class="button" data-quick-add="paket-${p.id}">${icon('plus')} Pilih paket</button></article>`).join('')}</div></section><section id="business-services"><div class="business-heading"><h2>Sentuhan <em>brand kamu.</em></h2></div><p class="business-subtitle">Detail label, kemasan, dan pemasangan. Minimum order mengikuti satuan pada setiap layanan.</p><div class="service-list">${services.map(s=>`<article class="service-item"><div><h3>${e(s.name)}</h3><p>${s.price===0?'Gratis sesuai ketentuan paket':rupiah(s.price)+' / '+e(s.unit)}</p><span>${s.minQty?'Minimum '+s.minQty+(s.unit==='pcs'?' pcs':s.unit.includes('roll')?' roll':s.unit==='lembar'?' lembar':' pcs'):'Ketentuan sesuai paket'}${s.leadTime?' · '+e(s.leadTime):''}</span></div><div class="service-detail">${s.colors?`<p>Warna: ${e(s.colors.join(', '))}</p>`:''}${s.models?`<p>Model: ${e(s.models.join(', '))}</p>`:''}${s.options?`<p>Posisi: ${e(s.options.join(', '))}</p>`:''}${s.note?`<p>${e(s.note)}</p>`:''}${s.material?`<p>${e(s.material)}</p>`:''}</div><a class="text-link" href="${whatsappLink(config.whatsapp,'Halo Vuyama, saya ingin konsultasi '+s.name+' sesuai katalog September 2026. Mohon informasi pilihan, minimum order, dan harga akhir.')}" target="_blank" rel="noopener" aria-label="Konsultasi ${e(s.name)}">Konsultasi ${icon('arrow')}</a></article>`).join('')}</div>${customDesignRules?.length?`<div class="business-note"><strong>Ketentuan desain custom</strong><ul>${customDesignRules.map(r=>`<li>${e(typeof r==='string'?r:JSON.stringify(r))}</li>`).join('')}</ul></div>`:''}</section>`;}

function render(scroll=true) {
 const active=document.activeElement;
 const focusState=!scroll&&active?.closest('#app')?{id:active.id,label:active.getAttribute('aria-label'),index:active.dataset.index,variant:active.dataset.variant,gallery:active.dataset.gallery}:null;
 const {path}=route(); let content,title;
 if(path==='/'){content=editorialHome();title=config.tagline;}
 else if(path==='/produk'){content=catalog();title='Koleksi';}
 else if(path.startsWith('/produk/')){const p=findProduct(path.slice(8));content=p?detail(p):notFound();title=p?.name||'Produk tidak ditemukan';}
 else if(path==='/keranjang'){content=cartPage();title='Keranjang';}
 else if(path==='/checkout'){content=checkoutPage();title='Checkout';}
 else if(path==='/usaha'){content=businessPage();title='Mulai Usaha';}
 else if(path==='/tentang'){content=aboutPage();title='Cerita Kami';}
 else if(path==='/favorit'){content=favoritesPage();title='Favorit';}
 else {content=notFound();title='Halaman tidak ditemukan';}
 document.title=`${title} — ${config.brand}`;
 document.body.classList.toggle('home-page',path==='/');
 app.innerHTML=header()+`<main id="main-content" class="${path==='/'?'home':'inner-page'}" tabindex="-1">${content}</main>`+footer();
 if(scroll) {window.scrollTo({top:0,behavior:'instant'}); if(path!=='/')document.querySelector('main').focus({preventScroll:true});}
 else if(focusState){const candidate=focusState.id?document.getElementById(focusState.id):[...app.querySelectorAll('button,input')].find(n=>n.getAttribute('aria-label')===focusState.label&&n.dataset.index===focusState.index&&n.dataset.variant===focusState.variant&&n.dataset.gallery===focusState.gallery);if(candidate&&!candidate.disabled)candidate.focus({preventScroll:true});}
 observeReveal(scroll);
}
function notFound(){return `<div class="empty-state"><span class="eyebrow">404</span><h1>Halaman belum ditemukan.</h1><p>Mari kembali ke koleksi favoritmu.</p>${link('#/produk','Lihat Koleksi','button')}</div>`;}
function observeReveal(animate=true){
 revealObserver?.disconnect();
 if(reduceMotion()||!('IntersectionObserver' in window))return;
 revealObserver=new IntersectionObserver(items=>{for(const item of items)if(item.isIntersecting){item.target.classList.add('in-view');revealObserver.unobserve(item.target);}},{threshold:.04,rootMargin:'0px 0px 28px 0px'});
 document.querySelectorAll('.section-heading,.story-copy,.product-card,.benefit-strip,.mosaic-copy').forEach((node,i)=>{
  if(!animate&&node.getBoundingClientRect().top<innerHeight)return;
  node.style.setProperty('--reveal-delay',node.classList.contains('product-card')?(i%3)*45+'ms':'0ms');node.classList.add('reveal');revealObserver.observe(node);
 });
 if(animate)document.querySelector('main').classList.add('page-enter');
}
function addToBag(id,variant,qty,button){
 const p=findProduct(id);if(!p)return;if(!canOrder(p,p.variants.find(v=>v.id===variant))){toast('Pilihan ini belum dapat dipesan. Hubungi admin.');return;}
 const before=count();cart=addItem(cart,id,variant,qty,products);const added=count()-before;
 if(!added){toast('Maksimum 99 pcs untuk varian ini.');return;}
 persist();updateHeader();toast(added+' '+p.name+' ditambahkan.',true);
 if(button){const html=button.innerHTML;button.disabled=true;button.classList.add('added');button.innerHTML=icon('check')+'<span>Ditambahkan</span>';setTimeout(()=>{if(button.isConnected){button.innerHTML=html;button.disabled=false;button.classList.remove('added');}},1000);}
 if(!reduceMotion()){const bag=document.querySelector('.cart-trigger');bag?.animate([{transform:'translateY(0)'},{transform:'translateY(-4px)'},{transform:'translateY(0)'}],{duration:360,easing:'ease-out'});}
}
function updateCardVariant(select){
 const p=findProduct(select.dataset.cardVariant),v=p?.variants.find(v=>v.id===select.value);if(!v)return;cardVariants.set(p.id,v.id);
 document.querySelectorAll('[data-product="'+p.id+'"]').forEach(node=>{
  node.querySelector('select').value=v.id;const add=node.querySelector('.card-add');add.disabled=!canOrder(p,v);add.querySelector('span').textContent=canOrder(p,v)?'Tambah ke keranjang':availabilityLabel(p,v);node.querySelector('.product-photo').classList.toggle('contain-photo',Boolean(p.contain||v.contain));const photo=node.querySelector('.card-primary');photo.src='assets/images/'+v.image;photo.alt=p.name+' — '+v.name;
  node.querySelector('.hover-image')?.remove();if(!reduceMotion())photo.animate([{opacity:.5},{opacity:1}],{duration:300});
 });
}
function updateHeader(){document.querySelectorAll('.cart-count').forEach(n=>{n.textContent=count();n.hidden=!count();});}
function openCart(){const active=cartDialog.contains(document.activeElement)?document.activeElement:null;const focus=active?{id:active.id,index:active.dataset.index,delta:active.dataset.delta,remove:active.dataset.remove}:null;cartDialog.innerHTML=`<div class="drawer-heading"><div><span class="eyebrow">YOUR SELECTION</span><h2 id="drawer-title">Keranjang <small>(${count()})</small></h2></div><button class="icon-button" data-action="close-cart" aria-label="Tutup keranjang">${icon('close')}</button></div><div class="drawer-items">${cart.length?cartRows(true):emptyCart()}</div>${cart.length?`<div class="drawer-footer"><div><span>${unpricedCount(cart,products)?'Subtotal sementara':'Subtotal produk'}</span><strong>${totalLabel()}</strong></div>${pendingNote()}<p>Ongkir dikonfirmasi bersama admin.</p>${link('#/checkout','Lanjut ke Checkout','button full-width')}<a class="drawer-cart-link" href="#/keranjang">Lihat Keranjang Lengkap</a></div>`:''}`;if(!cartDialog.open)cartDialog.showModal();else if(focus){const candidate=focus.id?document.getElementById(focus.id):[...cartDialog.querySelectorAll('button')].find(b=>focus.remove!==undefined?b.dataset.remove===focus.remove:b.dataset.index===focus.index&&b.dataset.delta===focus.delta);if(candidate&&!candidate.disabled)candidate.focus({preventScroll:true});}}
function updateCartView(){persist();updateHeader();if(cartDialog.open)openCart();if(['/keranjang','/checkout'].includes(route().path))render(false);}
function updateFilter(key,value){filterNavigation=true;const {params}=route();if(!value||value==='Semua'||value==='curated')params.delete(key);else params.set(key,value);const hash='/produk'+(params.size?'?'+params.toString():'');if(location.hash==='#'+hash){render(false);filterNavigation=false;}else location.hash=hash;}
function closeAll(){[cartDialog,searchDialog,imageDialog].forEach(d=>d.open&&d.close());}
document.addEventListener('click',event=>{
 const target=event.target.closest('button,a'); if(!target)return;
 if(target.dataset.section){event.preventDefault();document.getElementById(target.dataset.section)?.scrollIntoView({behavior:reduceMotion()?'auto':'smooth'});return;}
 if(target.classList.contains('skip-link')){event.preventDefault();document.querySelector('main').focus();document.querySelector('main').scrollIntoView();return;}
 if(target.closest('#cart-dialog')&&target.getAttribute('href')?.startsWith('#/'))cartDialog.close();
 if(target.hasAttribute('data-close-cart'))cartDialog.close();
 if(target.dataset.favorite){favorite(target.dataset.favorite);return;}
 if(target.dataset.quickAdd){const p=findProduct(target.dataset.quickAdd);addToBag(p.id,cardVariants.get(p.id)||p.variants.find(v=>canOrder(p,v))?.id||p.variants[0].id,1,target);return;}
 if(target.dataset.variant){selectedVariant=target.dataset.variant;galleryIndex=0;render(false);return;}
 if(target.dataset.gallery!==undefined){galleryIndex=Number(target.dataset.gallery);render(false);return;}
 if(target.dataset.zoom){imageDialog.innerHTML=`<button class="icon-button" data-action="close-image" aria-label="Tutup foto">${icon('close')}</button>${img(target.dataset.zoom,findProduct(detailId)?.name||'Foto produk','',true)}`;imageDialog.showModal();return;}
 if(target.dataset.add){addToBag(target.dataset.add,selectedVariant,selectedQuantity,target);return;}
 if(target.dataset.qty){const delta=Number(target.dataset.delta);if(target.dataset.qty==='detail'){selectedQuantity=quantity(selectedQuantity+delta);render(false);}else {const item=cart[Number(target.dataset.index)];if(item){item.qty=quantity(item.qty+delta);updateCartView();}}return;}
 if(target.dataset.remove!==undefined){cart.splice(Number(target.dataset.remove),1);updateCartView();toast('Produk dihapus dari keranjang.');return;}
 switch(target.dataset.action){
  case 'menu': {const nav=document.querySelector('.main-nav');const open=nav.classList.toggle('open');target.setAttribute('aria-expanded',String(open));break;}
  case 'cart': document.querySelector('#toast').classList.remove('visible');openCart();break;
  case 'close-cart': cartDialog.close();break;
  case 'close-search': searchDialog.close();break;
  case 'close-image': imageDialog.close();break;
  case 'search': searchDialog.innerHTML=`<div class="search-heading"><span class="eyebrow" id="search-title">TEMUKAN PILIHANMU</span><button class="icon-button" data-action="close-search" aria-label="Tutup pencarian">${icon('close')}</button></div><form data-search-form><label class="sr-only" for="search-input">Cari produk</label><div>${icon('search')}<input type="search" name="q" id="search-input" placeholder="Cari koleksi hijab…"><button type="submit" aria-label="Jalankan pencarian">${icon('arrow')}</button></div></form><p>Coba: Modal Viscose, Gradasi, atau Gana Instan.</p>`;searchDialog.showModal();document.querySelector('#search-input').focus();break;
  case 'filters': {filterPanelOpen=!filterPanelOpen;const panel=document.querySelector('.filter-panel');panel.classList.toggle('mobile-open',filterPanelOpen);document.querySelector('.filter-toggle').setAttribute('aria-expanded',String(filterPanelOpen));(filterPanelOpen?panel:document.querySelector('.catalog-toolbar')).scrollIntoView({behavior:reduceMotion()?'auto':'smooth',block:'start'});break;}
  case 'reset-filters': if(route().path==='/produk'&&!route().params.size)render(false);else location.hash='/produk';break;
  case 'scroll-story': event.preventDefault();document.querySelector('#story')?.scrollIntoView({behavior:reduceMotion()?'auto':'smooth'});break;
  case 'scroll-fashion': event.preventDefault();document.querySelector('#fashion-collection')?.scrollIntoView({behavior:reduceMotion()?'auto':'smooth'});break;
 }
});
document.addEventListener('change',event=>{
 const target=event.target;
 if(target.dataset.cardVariant){updateCardVariant(target);return;}
 if(target.hasAttribute('data-detail-select')){selectedVariant=target.value;galleryIndex=0;render(false);return;}
 if(target.dataset.filter){updateFilter(target.dataset.filter,target.value);return;}
 if(target.dataset.qtyInput){const value=quantity(target.value);if(target.dataset.qtyInput==='detail'){selectedQuantity=value;render(false);}else {const item=cart[Number(target.dataset.index)];if(item){item.qty=value;updateCartView();}}}
});
document.addEventListener('input',event=>{if(event.target.closest('#checkout-form')&&event.target.name){if(event.target.name==='phone')event.target.value=event.target.value.replace(/[\s().-]/g,'');customerDraft[event.target.name]=event.target.value;}});
document.addEventListener('submit',event=>{
 if(event.target.matches('[data-search-form]')){event.preventDefault();const q=new FormData(event.target).get('q').trim();searchDialog.close();location.hash='/produk'+(q?'?q='+encodeURIComponent(q):'');return;}
 if(event.target.id==='checkout-form'){
  event.preventDefault();if(!event.target.reportValidity())return;
  try {const data=Object.fromEntries(new FormData(event.target));customerDraft=data;const message=orderMessage(cart,products,data,config.brand);const url=whatsappLink(config.whatsapp,message);
   const fallback=document.querySelector('#whatsapp-fallback');fallback.hidden=false;fallback.innerHTML=`<strong>Pesanan siap dibuka di WhatsApp.</strong><p>Jika tab WhatsApp belum terbuka, gunakan tautan berikut. Pesanan belum terkirim sampai kamu menekan kirim di WhatsApp.</p><a class="text-link" href="${e(url)}" target="_blank" rel="noopener">Buka WhatsApp ${icon('arrow')}</a>`;
   window.open(url,'_blank','noopener,noreferrer');
  }catch(error){toast(error.message);}
 }
});
for(const dialog of [cartDialog,searchDialog,imageDialog])dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{closeAll();render(!filterNavigation);filterNavigation=false;});
window.addEventListener('storage',event=>{if(event.key===config.storageKey){cart=cleanCart(read(config.storageKey,[]),products);updateHeader();if(cartDialog.open)openCart();if(['/keranjang','/checkout'].includes(route().path))render(false);}});
render(false);


// Keep keyboard navigation and modal scrolling predictable on small screens.
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('.main-nav')?.classList.remove('open');document.querySelector('[data-action="menu"]')?.setAttribute('aria-expanded','false');}});

document.addEventListener('click',event=>{const nav=document.querySelector('.main-nav');if(nav?.classList.contains('open')&&!event.target.closest('.site-header')){nav.classList.remove('open');document.querySelector('[data-action="menu"]')?.setAttribute('aria-expanded','false');}});
